                    for (int dj = -1; dj <= 1; dj++)
                        if ((di != 0 || dj != 0) && i + di >= 0 && i + di < m && j + dj >= 0 && j + dj < n) live += board[i + di][j + dj] & 1;
                if (live == 3 || (board[i][j] == 1 && live == 2)) board[i][j] |= 2;
            }
        }
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) board[i][j] >>= 1;
    }
}

