class Solution {
public:
    bool wordBreak(string s, vector<string>& wordDict) {
        unordered_set<string> dict(wordDict.begin(), wordDict.end());
        int n = s.size();
        vector<bool> ok(n + 1, false);
        ok[0] = true;
        for (int i = 1; i <= n; i++)
            for (int j = 0; j < i && !ok[i]; j++)
                if (ok[j] && dict.count(s.substr(j, i - j))) ok[i] = true;
        return ok[n];
    }
};

